// Generated by scripts/build.mjs — do not edit dist/sw.js directly.
// Offline-first cache: once the box has loaded the site once, it keeps working
// without internet. A new deploy changes VERSION, which installs a fresh cache;
// the launcher reloads itself onto it when nobody is playing.
const VERSION = 'playbox-__VERSION__';
const PRECACHE = __PRECACHE__;
const RUNTIME_CDNS = ['cdnjs.cloudflare.com', 'cdn.jsdelivr.net'];
const CDN_CACHE = 'playbox-cdn-v1'; // survives deploys; these files are versioned by URL

async function cdnCacheFirst(req) {
  const cache = await caches.open(CDN_CACHE);
  const hit = await cache.match(req);
  if (hit) return hit;
  const res = await fetch(req);
  if (res.ok) cache.put(req, res.clone());
  return res;
}

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches
      .open(VERSION)
      .then((cache) => cache.addAll(PRECACHE))
      .then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== VERSION && k !== CDN_CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  // HEAD ("does this file exist?"): answer from the cache when we have it, so it works offline.
  if (req.method === 'HEAD' && new URL(req.url).origin === self.location.origin) {
    event.respondWith(
      caches.open(VERSION).then(async (cache) => {
        const hit = await cache.match(req.url, { ignoreSearch: true });
        if (hit) return new Response(null, { status: hit.status, headers: hit.headers });
        return fetch(req);
      }),
    );
    return;
  }
  if (req.method !== 'GET') return;
  // fetch(url, { cache: 'no-store' }) skips the cache — used to check for a newer deploy.
  if (req.cache === 'no-store') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) {
    // The natural voice's runtime (ONNX Runtime + phonemizer wasm) comes from these
    // CDNs; keep a copy so speech still works offline. (The voice model itself is
    // stored by the voice engine in the browser's private storage.)
    if (RUNTIME_CDNS.includes(url.hostname)) event.respondWith(cdnCacheFirst(req));
    return;
  }

  event.respondWith(
    caches.open(VERSION).then(async (cache) => {
      // ignoreSearch so ?input=sim etc. still hit the cached page.
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        const res = await fetch(req);
        if (res.ok) cache.put(req, res.clone());
        return res;
      } catch (err) {
        if (req.mode === 'navigate') {
          const home = await cache.match('./');
          if (home) return home;
        }
        throw err;
      }
    }),
  );
});
